create schema private; create schema auth; create schema storage;
create role anon; create role authenticated; grant usage on schema public,private,auth,storage to authenticated,anon;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql as $$select nullif(current_setting('test.uid',true),'')::uuid$$;
create function private.account_access_allowed() returns boolean language sql as $$select coalesce(current_setting('test.allowed',true),'true')<>'false'$$;
create function private.has_company_feature(uuid,text) returns boolean language sql as $$select coalesce(current_setting('test.manage',true),'false')='true'$$;
create table public.companies(id uuid primary key);
create table public.company_members(company_id uuid,user_id uuid,role text);
create table public.workers(id uuid primary key,company_id uuid,user_id uuid,name text,status text);
create table public.route_assignments(id uuid primary key,company_id uuid);
create table public.sites(id uuid primary key,name text);
create table public.route_stops(id uuid primary key,route_assignment_id uuid,site_id uuid,stop_order integer,address text,source_label text);
create table public.daily_reports(id uuid primary key,company_id uuid,site_id uuid,route_assignment_id uuid,report_date date,updated_by uuid,status text);
create table public.daily_report_workers(report_id uuid,worker_id uuid);
create table public.attendance_verifications(id uuid primary key,company_id uuid,worker_id uuid,site_id uuid,route_assignment_id uuid,work_date date,event_type text,source_clock_in_id uuid,daily_report_id uuid,verification_mode text,capture_contract_version integer);
create function public.get_attendance_capture_capability(p_company_id uuid) returns jsonb language sql as $$select jsonb_build_object('capture_enabled',coalesce(current_setting('test.capture',true),'true')='true')$$;
create table storage.buckets(id text primary key,name text,public boolean);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text);
alter table storage.objects enable row level security;
grant insert,select,update,delete on storage.objects to authenticated;
grant select on public.company_members,public.workers to authenticated;
